(function(){"use strict";var CHAVE="sl_chat_amplo",ATTR="data-sl-chat-amplo";try{var m=location.search.match(/[?&]chatamplo=([01])/);if(m)localStorage.setItem(CHAVE,m[1])}catch(e){}function ligado(){try{return localStorage.getItem(CHAVE)!=="0"}catch(e){return true}}var H="html["+ATTR+"]["+ATTR+"]";var PAINEL_TOPO=H+' .panel > div[style*="padding: 14px 20px"][style*="border-bottom"]';var ETIQUETAS=H+' .panel > div[style*="padding: 8px 20px"][style*="font-size: 12px"]';var MENSAGENS=H+' .panel > div[style*="--chat-bg"]';var CAIXA=H+' .panel > div[style*="padding: 14px"][style*="border-top"]';var CSS=[H+" .content{padding-top:8px!important;padding-bottom:8px!important}",H+' .content > div > div[style*="margin-bottom: 14px"][style*="flex-wrap: wrap"]{margin-bottom:8px!important}',PAINEL_TOPO+"{padding:6px 14px!important;gap:6px 8px!important}",ETIQUETAS+"{padding:3px 14px!important}",MENSAGENS+"{padding:12px 16px!important;gap:6px!important}",CAIXA+"{padding:8px 12px!important}",CAIXA+' > div[style*="margin-bottom: 8px"]{margin-bottom:4px!important}',CAIXA+' > div[style*="margin-bottom: 8px"] .btn{padding-top:3px!important;padding-bottom:3px!important;'+"min-height:28px!important;height:auto!important}"].join("\n");function estilo(){if(document.getElementById("sl-chat-amplo-css"))return;var s=document.createElement("style");s.id="sl-chat-amplo-css";s.textContent=CSS;(document.head||document.documentElement).appendChild(s)}function aplicar(){var h=document.documentElement;if(!h){document.addEventListener("DOMContentLoaded",aplicar);return}var ok=ligado()&&/^\/chat(\/|$)/.test(location.pathname);if(ok){estilo();if(!h.hasAttribute(ATTR))h.setAttribute(ATTR,"")}else if(h.hasAttribute(ATTR))h.removeAttribute(ATTR)}["pushState","replaceState"].forEach((function(k){var orig=history[k];if(typeof orig!=="function")return;history[k]=function(){var r=orig.apply(this,arguments);setTimeout(aplicar,0);return r}}));window.addEventListener("popstate",aplicar);aplicar()})();